import{_ as a,o as e,c as s,a2 as n}from"./chunks/framework.CMIYMl9C.js";const b=JSON.parse('{"title":"术语与边界","description":"","frontmatter":{},"headers":[],"relativePath":"getting-started/concepts.md","filePath":"getting-started/concepts.md","lastUpdated":null}'),d={name:"getting-started/concepts.md"};function r(o,t,i,l,p,c){return e(),s("div",null,[...t[0]||(t[0]=[n(`<h1 id="术语与边界" tabindex="-1">术语与边界 <a class="header-anchor" href="#术语与边界" aria-label="Permalink to &quot;术语与边界&quot;">​</a></h1><p>本页给出后续文档使用的精确定义。先区分这些对象，可以避免把“任务”“目标”“episode”“一次模型 推理”和“一次评测运行”混为一谈。</p><h2 id="核心术语" tabindex="-1">核心术语 <a class="header-anchor" href="#核心术语" aria-label="Permalink to &quot;核心术语&quot;">​</a></h2><table tabindex="0"><thead><tr><th>术语</th><th>在 HarnessVLN 中的含义</th></tr></thead><tbody><tr><td>Run</td><td>一次 CLI / API 批量运行；包含一个 Bench split 的若干 Task</td></tr><tr><td>Case</td><td>Bench 内部对象，含公开 Task、私有 setup 与评分 truth</td></tr><tr><td>Task</td><td>交给 Agent 的一次完整导航会话；可能包含连续多个 Goal</td></tr><tr><td>Goal</td><td>当前公开的导航目标，含 instruction、modality 和 public 元数据</td></tr><tr><td>Job</td><td>Agent 委托给 VLN 的一次导航请求；一个 Task 可启动多个 Job</td></tr><tr><td>Tool call</td><td>组件经 ToolBus 发起的一次类型化能力调用</td></tr><tr><td>Native step</td><td>模拟器或真机的一次底层推进；不一定等于一个导航动作</td></tr><tr><td>Record</td><td>一个 Case 的 Task 结果、指标、错误和审计集合</td></tr><tr><td>Manifest</td><td>一次 Run 的可复现实验记录，原子写入 JSON</td></tr></tbody></table><h2 id="task-不总等于单目标-episode" tabindex="-1">Task 不总等于单目标 episode <a class="header-anchor" href="#task-不总等于单目标-episode" aria-label="Permalink to &quot;Task 不总等于单目标 episode&quot;">​</a></h2><p>普通 R2R case 通常是一个 Task 对应一个 Goal。GOAT 则把一个含 5 至 10 个目标的复合 episode 表示成<strong>一个 Task</strong>：Agent 只看到当前 Goal，调用 <code>nav.goal.finish</code> 后 Environment 才揭示下一个。 模拟器 session 和 Task 级空间记忆不 reset。这正是终身/跨目标导航与“把每个 goal 当独立 case” 的关键区别。</p><h2 id="公开数据与私有数据" tabindex="-1">公开数据与私有数据 <a class="header-anchor" href="#公开数据与私有数据" aria-label="Permalink to &quot;公开数据与私有数据&quot;">​</a></h2><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>BenchmarkCase</span></span>
<span class="line"><span>  task: NavTask              -&gt; Agent 可见</span></span>
<span class="line"><span>    task_id</span></span>
<span class="line"><span>    scene_id</span></span>
<span class="line"><span>    goal: NavGoal</span></span>
<span class="line"><span>      goal_id</span></span>
<span class="line"><span>      instruction</span></span>
<span class="line"><span>      modality</span></span>
<span class="line"><span>      public</span></span>
<span class="line"><span>    public</span></span>
<span class="line"><span>  setup: Mapping             -&gt; Environment 可用，Agent 不可见</span></span>
<span class="line"><span>  truth: Mapping             -&gt; Benchmark.score 可用，Agent 不可见</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br><span class="line-number">12</span><br></div></div><p>起始位姿、原生 episode、最短路径和最终答案等不应塞进 <code>NavTask.public</code>。公开字段应只包含任务 协议明确允许 Agent 使用的信息。</p><h2 id="状态的所有权" tabindex="-1">状态的所有权 <a class="header-anchor" href="#状态的所有权" aria-label="Permalink to &quot;状态的所有权&quot;">​</a></h2><table tabindex="0"><thead><tr><th>状态</th><th>所有者</th><th>默认寿命</th></tr></thead><tbody><tr><td>Agent workflow / 对话历史</td><td>Agent</td><td>Task</td></tr><tr><td>帧历史、KV cache、大小脑线程</td><td>VLN</td><td>Job 或 run，取决于实现</td></tr><tr><td>仿真器 session、机器人连接</td><td>Environment</td><td>Task</td></tr><tr><td>当前与未来复合 Goal</td><td>Environment / Bench</td><td>Task</td></tr><tr><td>Landmark 内存文件</td><td>Memory</td><td>可跨 Task / Run</td></tr><tr><td>case 序号与结果顺序</td><td>Runner</td><td>Run</td></tr></tbody></table><p>Harness 不把某个模块的内部状态提升为公共对象。需要跨边界的信息必须经过显式 schema 或工具。</p><h2 id="terminal、goal-finish-与-stop" tabindex="-1"><code>terminal</code>、<code>goal.finish</code> 与 <code>stop</code> <a class="header-anchor" href="#terminal、goal-finish-与-stop" aria-label="Permalink to &quot;\`terminal\`、\`goal.finish\` 与 \`stop\`&quot;">​</a></h2><ul><li><code>nav.goal.finish</code>：提交当前 Goal 的结果。复合任务可能返回下一个 Goal，Task 仍继续。</li><li><code>nav.stop</code>：Agent 宣布整个 Task 结束，触发 Harness 终止竞争。</li><li><code>Environment.wait_terminal()</code>：原生环境自行终止，例如动作预算耗尽或服务失败。</li><li><code>NavigationResult.terminal</code>：上述信号中第一个成功认领终止状态者。</li></ul><p>因此 VLN 输出 STOP 不直接等于整个 Task 结束。VLN Job 先结束，Agent 再决定提交 Goal、进入下一 Goal、重试，或结束 Task。</p><h2 id="profile、requirements-与-tool-schema" tabindex="-1">Profile、requirements 与 tool schema <a class="header-anchor" href="#profile、requirements-与-tool-schema" aria-label="Permalink to &quot;Profile、requirements 与 tool schema&quot;">​</a></h2><p>这三个概念解决不同问题：</p><ul><li><code>NavigationProfile</code> 描述 Environment 实际提供的观测通道、动作集合、单位和相机参数。</li><li><code>VLNNavigator.requirements</code> 描述模型正常运行必须满足的 profile。</li><li><code>Tool.input_schema</code> 校验某次调用的参数结构。</li></ul><p>Profile 在组件启动阶段阻止不兼容组合；tool schema 在每次调用时阻止非法输入。二者不可互相替代。</p><h2 id="验证等级" tabindex="-1">验证等级 <a class="header-anchor" href="#验证等级" aria-label="Permalink to &quot;验证等级&quot;">​</a></h2><p>文档使用四类状态，不把“写了 adapter”视为已完成兼容：</p><table tabindex="0"><thead><tr><th>等级</th><th>含义</th></tr></thead><tbody><tr><td><code>contract</code></td><td>接口与 mock/单测成立</td></tr><tr><td><code>data_contract</code></td><td>官方 case 到原生配置/episode 的映射成立，但大型资源未完整运行</td></tr><tr><td>real smoke / fixed trace</td><td>真实依赖上跑过一个或固定若干 case，并保留证据</td></tr><tr><td>official parity</td><td>相同版本、split 和评分器与官方实现对照通过</td></tr></tbody></table><p>当前三个真实 VLN 已达到 R2R-CE 固定三例 trace，官方 parity 仍是发布门禁。</p>`,23)])])}const u=a(d,[["render",r]]);export{b as __pageData,u as default};
